  ('23301809-2dc9-5131-b387-6b69c026ac3c', null, (select id from public.skills where slug = 'read-g5-evidence-inference'), null, 'hard',
   $q$A hiker finds long scratches on flat bedrock, and all of them run from north to south. Based on the passage, which conclusion is best supported?$q$, $q$[{"text":"A glacier once moved across this rock in a north and south direction.","is_correct":true},{"text":"A glacier is still sitting on top of this rock under the ground.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"An erratic boulder rolled across the rock after the ice melted.","is_correct":false,"misconception_token":"misapplies-detail"},{"text":"A river once flowed over this rock and cut the scratches into it.","is_correct":false,"misconception_token":"confuses-cause-effect"}]$q$::jsonb, $q$A glacier once moved across this rock in a north and south direction.$q$, $q$Paragraph 3 says rocks in a glacier leave scratches that "all point in the same direction, the direction the ice traveled." The passage connects rivers to V-shaped valleys, not to scratches on bedrock.$q$, 'draft', '9bd03cc1-2186-54a1-b9a6-fc9ce87d99ca')
