insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('be6f451d-b89d-521b-9668-dcbabc3d4534', 'rg5-figurative-language-p02', (select id from public.skills where slug = 'read-g5-figurative-language'), null,
        '3-5', $q$The Clever Octopus$q$, $q$The octopus is one of the smartest animals in the sea. It has no bones, so its soft body can squeeze through a gap as small as a coin. An octopus is a living escape artist.

An octopus has eight arms, and each arm is lined with suckers. These suckers can taste as well as grip. When an octopus explores a rock, its arms work like busy hands searching a dark closet.

Octopuses are also masters of disguise. Special cells in their skin let them change color in a flash. A gray octopus can turn sandy brown to match the sea floor. To a hungry shark, the octopus seems to vanish into thin air.

If a predator does spot it, the octopus has another trick. It squirts a cloud of dark ink and darts away. The ink confuses the enemy for a few seconds, which is all the octopus needs.

Scientists who study octopuses in aquariums have watched them unscrew jar lids to reach food inside. Some have even slipped out of their tanks at night to explore. These clever creatures prove the old saying that where there is a will, there is a way.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
