  ('f68c51d4-7d9f-5e61-b81a-7ce6c0559f5b', null, (select id from public.skills where slug = 'read-g5-literary-structure-pov'), null, 'medium',
   $q$Priya thinks Daniel frowned because she was slow. According to Daniel, why did he really frown?$q$, $q$[{"text":"He knew he was about to win the game with his next move.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"He was surprised by a move he had completely missed.","is_correct":true},{"text":"He was annoyed that Priya took so long to move.","is_correct":false,"misconception_token":"confuses-character-views"},{"text":"He wanted the game to end so he could see his coach.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$He was surprised by a move he had completely missed.$q$, $q$Daniel says, "I frowned because I had completely missed that move." Being annoyed at her slowness is only what Priya imagined from her side of the board.$q$, 'draft', 'f3482401-1d06-52a3-bee6-7d39d4414a12')
