  ('1e098458-7174-5898-811f-d12f899e243a', null, (select id from public.skills where slug = 'read-g5-literary-structure-pov'), null, 'medium',
   $q$How are the first three stanzas arranged?$q$, $q$[{"text":"They each tell about a different bus in the city.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"They follow one day in order, from early morning to night.","is_correct":true},{"text":"They move backward in time, from night to morning.","is_correct":false,"misconception_token":"reverses-sequence"},{"text":"They follow the bus through four seasons of the year.","is_correct":false,"misconception_token":"misreads-structure"}]$q$::jsonb, $q$They follow one day in order, from early morning to night.$q$, $q$The stanzas move from "Before the sun" to "three o'clock" to "By night," which is one day in order. The poem never mentions seasons, so they are not arranged by time of year.$q$, 'draft', '1189a38b-da30-5eac-bcdf-dc53c9245399')
