-- Passage rg5-main-idea-summary-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('68afe90d-6545-5eb0-998c-420cd508427f', 'rg5-main-idea-summary-p05', (select id from public.skills where slug = 'read-g5-main-idea-summary'), null,
        '3-5', $q$From Sand to Stained Glass$q$, $q$Stained glass windows glow with bright color when sunlight shines through them. Making one takes skill, patience and many careful steps.

The process begins with glass. Glass is made by heating sand until it melts into a thick liquid. To give the glass color, glassmakers stir in small amounts of metal powders. A little copper can make the glass green or blue. Other metals create reds, purples and yellows.

Next, an artist draws a full-size plan of the window. The plan shows where each color will go. Using the drawing as a guide, the artist cuts the colored glass into small pieces. Each piece must fit its spot exactly.

Then the pieces are joined together. The artist wraps or frames each piece with thin strips of lead. Where the strips meet, the artist melts a little metal to hold them tight. The dark lines of lead outline the shapes, almost like lines in a coloring book.

Finally, the finished panel is sealed so rain cannot leak through, and it is set into a window frame. A large window can take months to complete. When it is done, it may last for hundreds of years.$q$, 'draft')
