-- Passage rg5-story-details-inference-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('b6cd1b52-76b9-5bf1-a125-2b95eafc8960', 'rg5-story-details-inference-p06', (select id from public.skills where slug = 'read-g5-story-details-inference'), null,
        '3-5', $q$The Water Bucket$q$, $q$In the winter of 1889, the Harmon Creek school had one room, one teacher, and one wooden bucket. Every morning, an older student carried the bucket to the creek. The student filled it with drinking water for the day.

This week, the job belonged to eleven-year-old Hanna Lindgren. On Monday, she found the creek covered with ice. She cracked it with a rock, filled the bucket, and carried it back with frozen fingers.

On Tuesday, the ice was thicker. The rock bounced right off it. Hanna stood on the bank, breathing clouds into the cold air. Then she remembered the stove.

She hurried inside, where Miss Abernathy was feeding sticks into the iron stove. Hanna scooped the bucket full of clean snow from the drift by the door. She set it on the warm top of the stove. By the time the younger children arrived, stamping their boots, the snow had melted into water.

Miss Abernathy dipped the tin cup and took a sip. She looked at Hanna for a long moment. Then she wrote something on a slip of paper. She tucked it into the book where she kept the names for the spring awards.

Hanna did not see what it said. But on Wednesday, Miss Abernathy asked her to explain her idea to the whole class.$q$, 'draft')
