  ('92d1bfb7-db77-5e52-8720-5de0eec3673f', null, (select id from public.skills where slug = 'read-g5-theme-summary'), null, 'easy',
   $q$Which sentence best states the lesson of the fable?$q$, $q$[{"text":"Small webs always catch more flies than large webs do.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Living on the ground is safer than living high in a tree.","is_correct":false,"misconception_token":"misreads-character"},{"text":"When something keeps failing, look closely and try a new plan.","is_correct":true},{"text":"Strong winds can destroy almost anything that animals build.","is_correct":false,"misconception_token":"topic-not-theme"}]$q$::jsonb, $q$When something keeps failing, look closely and try a new plan.$q$, $q$The spider succeeds after she studies the wind and moves her web, then says she stopped "doing the same thing." The grasshopper's idea about the ground is the advice the spider ignores, so it is not the lesson.$q$, 'draft', '10129b83-73e0-5e8b-80f8-384b42794b81')
