  ('7d72466f-3fe8-54c9-8ed2-f423ecfba93d', null, (select id from public.skills where slug = 'read-g5-theme-summary'), null, 'hard',
   $q$Why is it important to the theme that the Otters finish third instead of first?$q$, $q$[{"text":"It shows that Kenji's success comes from his effort, not from winning.","is_correct":true},{"text":"It explains why the team will need more practice before the next meet.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It shows that the coach made a mistake by choosing Kenji as anchor.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It proves that the other teams had much better swimmers than the Otters.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It shows that Kenji's success comes from his effort, not from winning.$q$, $q$Because the team does not win, the cheering and Kenji's pride must come from his best time and from moving the team up a place. His teammate praises him, so the story does not suggest the coach was wrong.$q$, 'draft', '258f9122-b6b9-50eb-a014-594b0ffde069')
