values
  ('4f54e2e0-1cb6-55e7-927e-5e542854015a', null, (select id from public.skills where slug = 'read-g6-argument-evidence'), null, 'hard',
   $q$Which statement best evaluates the evidence from Maple Falls?$q$, $q$[{"text":"It is irrelevant, because the passage is about health, not about safety.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"It proves that no child walking with a group will ever be hurt crossing a street.","is_correct":false,"misconception_token":"overgeneralizes"},{"text":"It shows how parents felt, but not whether children there were actually safer.","is_correct":true},{"text":"It is the author's main evidence that walking school buses reduce car traffic.","is_correct":false,"misconception_token":"mismatched-reason"}]$q$::jsonb, $q$It shows how parents felt, but not whether children there were actually safer.$q$, $q$Parents feeling "comfortable" is a report of feelings, not a measure of accidents or safety. It supports the safety reason, so it is not about traffic and is not irrelevant.$q$, 'draft', 'd2924bae-388e-50cc-95eb-a4a6bff6589a')
